// Des: Tests for M17 bench: list parsing, tally, table text
// Flo: mock site + mock vendor > benchRun over a list > assert per-level hit rate and per-tier cost rows
// I/O: mock server > pass or fail (no leaks)
// Run: zig build test
// ===================================================================
const std = @import("std"); const benc = @import("ct-ctrl-benc.zig"); const rigz = @import("te-brow-rig.zig");
const allo = std.testing.allocator;
test "list parser: levels, comments, bad lines" { var aren = std.heap.ArenaAllocator.init(allo); defer aren.deinit(); const got2 = try benc.listRead(aren.allocator(), "# c\nL1 http://a.test/x\n\nL6 http://b.test/y\n"); try std.testing.expectEqual(@as(usize, 2), got2.len); try std.testing.expectEqual(@as(u8, 6), got2[1].level); try std.testing.expectError(error.BadUsage, benc.listRead(aren.allocator(), "http://a.test/x")); try std.testing.expectError(error.BadUsage, benc.listRead(aren.allocator(), "L0 http://a.test/x")); try std.testing.expectError(error.BadUsage, benc.listRead(aren.allocator(), "L10 http://a.test/x")); }
test "bench: free pages and vendor pages tallied, failures listed, table written" { var rig3: rigz.Rigg = undefined; try rig3.upzz(.{}); defer rig3.down(); rig3.ladz.sess = null; var aren = std.heap.ArenaAllocator.init(allo); defer aren.deinit(); const aaaz = aren.allocator(); var b1zz: [64]u8 = undefined; var b2z2: [64]u8 = undefined; var b3zz: [64]u8 = undefined; var b4zz: [64]u8 = undefined; const items = [_]benc.Item{ .{ .level = 1, .urlz = try aaaz.dupe(u8, rig3.srv2.urlzOfzz(&b1zz, "/p1")) }, .{ .level = 1, .urlz = try aaaz.dupe(u8, rig3.srv2.urlzOfzz(&b2z2, "/p2")) }, .{ .level = 5, .urlz = try aaaz.dupe(u8, rig3.srv2.urlzOfzz(&b3zz, "/e403")) }, .{ .level = 6, .urlz = try aaaz.dupe(u8, rig3.srv2.urlzOfzz(&b4zz, "/img")) } }; const rslt = try benc.bencRunz(aaaz, &rig3.ladz, &items); try std.testing.expect(rslt[0].good and rslt[1].good and rslt[2].good); try std.testing.expect(!rslt[3].good); try std.testing.expectEqual(@as(i64, 1), rslt[0].tier); try std.testing.expect(rslt[2].tier >= 2); const tex2 = try benc.bencText(aaaz, rslt, "2026-11-21"); try std.testing.expect(std.mem.indexOf(u8, tex2, "## Bench 2026-11-21") != null); try std.testing.expect(std.mem.indexOf(u8, tex2, "| L1 | 2 | 2 | 100% | 0 |") != null); try std.testing.expect(std.mem.indexOf(u8, tex2, "| L6 | 1 | 0 | 0% | 0 |") != null); try std.testing.expect(std.mem.indexOf(u8, tex2, "- failed L6:") != null); try std.testing.expect(std.mem.indexOf(u8, tex2, "T1 own | 2 |") != null); }
